// Adapts the incoming webhook payload into the same shape Parse CSV (tolerant) expects.
const body = $input.first().json.body || $input.first().json;
const csvText = body.csv || body.data || '';
return [{ json: { data: csvText } }];

// Tolerant CSV parser -- ragged rows repaired + flagged, never dropped.
const text = $input.first().json.data;

function splitCsvLine(line) {
  const fields = [];
  let cur = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (inQuotes) {
      if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else { inQuotes = false; } }
      else { cur += ch; }
    } else if (ch === '"') { inQuotes = true; }
    else if (ch === ',') { fields.push(cur); cur = ''; }
    else { cur += ch; }
  }
  fields.push(cur);
  return fields;
}

const lines = text.split(/\r\n|\n|\r/).filter((l) => l.length > 0);
if (lines.length === 0) return [];

const header = splitCsvLine(lines[0]).map((h) => h.trim());
const nExpected = header.length;
const results = [];

for (let i = 1; i < lines.length; i++) {
  const flags = [];
  let fields = splitCsvLine(lines[i]);
  if (fields.every((f) => f.trim() === '')) continue;

  if (fields.length < nExpected) {
    flags.push(`structural: expected ${nExpected} columns, got ${fields.length} at line ${i + 1}`);
    while (fields.length < nExpected) fields.push('');
  } else if (fields.length > nExpected) {
    const notesIdx = header.indexOf('raw_notes') >= 0 ? header.indexOf('raw_notes') : nExpected - 2;
    const head = fields.slice(0, notesIdx);
    const hasTailCol = nExpected - notesIdx - 1 === 1;
    const tail = hasTailCol ? fields[fields.length - 1] : null;
    const mergedNotes = fields.slice(notesIdx, fields.length - (hasTailCol ? 1 : 0)).join(',');
    let repaired = [...head, mergedNotes];
    if (tail !== null) repaired.push(tail);
    while (repaired.length < nExpected) repaired.push('');
    fields = repaired.slice(0, nExpected);
    flags.push(`structural: expected ${nExpected} columns, got more at line ${i + 1} (auto-merged into raw_notes)`);
  }

  const row = {};
  header.forEach((h, idx) => { row[h] = fields[idx] !== undefined ? fields[idx] : ''; });
  row._line_no = i + 1;
  row._ingest_flags = flags;
  results.push({ json: row });
}
return results;

// Deterministic cleaning + classification. LLM does judgment calls only --
// this node does lookups: email format, free-mail-domain check, source rank,
// cheap placeholder-name pre-check (Validator LLM still owns the final call).

const FREE_MAIL_DOMAINS = new Set(["gmail.com", "yahoo.com", "outlook.com", "hotmail.com", "icloud.com", "aol.com", "protonmail.com", "proton.me", "mail.com", "zoho.com", "yandex.com", "live.com", "msn.com", "rediffmail.com", "gmx.com", "fastmail.com"]);
const PLACEHOLDER_NAMES = new Set(['abc', 'xyz', 'zys', 'test', 'test test', 'n/a', 'na', 'asdf', 'xxx', '']);
const SOURCE_RANK = { referral: 2, event: 1, web: 0 };

const staticData = $getWorkflowStaticData('node');
if (!staticData.seenEmails) staticData.seenEmails = {};

const row = $json;
const flags = [...(row._ingest_flags || [])];

const leadId = (row.lead_id || '').trim();
const name = (row.name || '').trim();
const email = (row.email || '').trim().toLowerCase();
const company = (row.company || '').trim();
const rawNotes = (row.raw_notes || '').trim();
const source = (row.source || '').trim().toLowerCase() || 'unknown';

const emailRe = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
const emailValid = emailRe.test(email);

let emailType = 'blank';
let domain = null;
if (emailValid) {
  domain = email.split('@')[1];
  emailType = FREE_MAIL_DOMAINS.has(domain) ? 'personal' : 'company';
} else if (email) {
  flags.push(`malformed email: '${email}'`);
}

if (!leadId) flags.push('missing lead_id');
if (!company) flags.push('missing company');
if (!rawNotes) flags.push('empty raw_notes');

const namePlaceholderSuspected = PLACEHOLDER_NAMES.has(name.toLowerCase());
if (namePlaceholderSuspected) flags.push(`name looks like a placeholder: '${name}'`);

if (emailValid) {
  if (staticData.seenEmails[email]) {
    flags.push(`possible duplicate of ${staticData.seenEmails[email]} (same email)`);
  } else {
    staticData.seenEmails[email] = leadId || `line ${row._line_no}`;
  }
}

const sourceRank = SOURCE_RANK.hasOwnProperty(source) ? SOURCE_RANK[source] : 0;

return {
  json: {
    lead_id: leadId || `UNKNOWN-${row._line_no}`,
    name: name || null,
    name_placeholder_suspected: namePlaceholderSuspected,
    email: email || null,
    email_valid: emailValid,
    email_type: emailType,          // company | personal | blank
    domain,
    company: company || null,
    raw_notes: rawNotes || null,
    source,
    source_rank: sourceRank,        // referral=2, event=1, web/unknown=0
    flags,
  },
};

// Guardrail: sanity-check Clean & Validate's output shape before it reaches the LLM.
const r = $json;
const problems = [];
if (!r.lead_id) problems.push('missing lead_id after cleaning');
if (!['company', 'personal', 'blank'].includes(r.email_type)) problems.push('email_type out of range');
if (typeof r.source_rank !== 'number') problems.push('source_rank not numeric');
return { json: { ...r, guardrail_clean_ok: problems.length === 0, guardrail_clean_problems: problems } };

// Guardrail: check the Validator LLM's structured output is actually usable.
// If the parser failed or returned something out of range, flag rather than crash.
const lead = $('Guardrail: Clean Check').item.json;
const out = $json.output || $json; // structured output parser puts result under `output` in most n8n versions
const problems = [];

const validIntents = ['blank', 'gibberish', 'browsing', 'inquiry', 'demo', 'complaint', 'order'];
const intent = (out.intent || '').toLowerCase();
if (!validIntents.includes(intent)) problems.push(`intent '${intent}' not in allowed set`);

const clarity = (out.clarity || '').toLowerCase();
if (!['yes', 'no'].includes(clarity)) problems.push(`clarity '${clarity}' not yes/no`);

const repeatCustomer = (out.repeat_customer || 'unclear').toLowerCase();

return {
  json: {
    ...lead,
    validator_ok: problems.length === 0,
    validator_problems: problems,
    name_valid: problems.length === 0 ? !!out.name_valid : !lead.name_placeholder_suspected,
    name_flag_reason: out.name_flag_reason || null,
    company_size_tier: out.company_size_tier || 'unknown',
    company_networth_estimate: out.company_networth_estimate || null,
    intent: validIntents.includes(intent) ? intent : 'blank',
    clarity: ['yes', 'no'].includes(clarity) ? clarity : 'no',
    repeat_customer: repeatCustomer,
  },
};

// Deterministic scoring matrix -- the priority decision is a rule, not an LLM guess.
const r = $json;

const INTENT_POINTS = { blank: 0, gibberish: 1, browsing: 2, inquiry: 3, demo: 4, complaint: 5, order: 6 };
const EMAIL_POINTS = { company: 2, personal: 0, blank: -1 };
const SIZE_BONUS = { large: 2, medium: 1, small: 0, unknown: 0 };

let intentPoints = INTENT_POINTS.hasOwnProperty(r.intent) ? INTENT_POINTS[r.intent] : 0;
if (r.clarity === 'no') intentPoints = Math.min(intentPoints, 4); // unclear notes cap the score

const emailPoints = EMAIL_POINTS.hasOwnProperty(r.email_type) ? EMAIL_POINTS[r.email_type] : 0;
const companyPoints = (r.company ? 1 : 0) + (SIZE_BONUS.hasOwnProperty(r.company_size_tier) ? SIZE_BONUS[r.company_size_tier] : 0);
const sourcePoints = typeof r.source_rank === 'number' ? r.source_rank : 0;
const repeatBonus = r.repeat_customer === 'yes' ? 1 : 0;

const totalScore = intentPoints + emailPoints + companyPoints + sourcePoints + repeatBonus;
const tier = totalScore >= 9 ? 'Hot' : totalScore >= 4 ? 'Warm' : 'Cold';

const reasons = [];
if (tier === 'Cold') reasons.push('low total score');
if (r.clarity === 'no') reasons.push('low clarity in raw_notes');
if (r.name_valid === false) reasons.push('name failed validation');
if (r.email_type === 'blank' && !r.company) reasons.push('no email and no company -- data insufficient');
if (r.guardrail_clean_ok === false) reasons.push('ingestion guardrail failed');
if (r.validator_ok === false) reasons.push('validator guardrail failed');

return {
  json: {
    ...r,
    intent_points: intentPoints,
    email_points: emailPoints,
    company_points: companyPoints,
    source_points: sourcePoints,
    repeat_bonus: repeatBonus,
    total_score: totalScore,
    tier,
    needs_judge_check: reasons.length > 0,
    needs_judge_reasons: reasons,
  },
};

