=A lead scoring pipeline flagged this lead as needing a human-review decision. Given the reasons below, decide whether a human should actually look at it before it's acted on.

Lead: {{ $json.name || '(no name)' }} at {{ $json.company || '(no company)' }}
Notes: """{{ $json.raw_notes || '(none)' }}"""
Computed tier: {{ $json.tier }} (score {{ $json.total_score }})
Intent: {{ $json.intent }}, clarity: {{ $json.clarity }}
Flagged because: {{ $json.needs_judge_reasons.join(', ') }}

Return needs_human_review (true/false) and a one-phrase review_reason.

parameters.jsCode:
// Guardrail after the Judge chain: fall back safely if the judge call/parse failed.
const lead = $('Score & Tier').item.json;
const out = $json.output || $json;
const needsReview = typeof out.needs_human_review === 'boolean' ? out.needs_human_review : true; // fail safe: unclear -> review
return {
  json: {
    ...lead,
    judge_ran: true,
    needs_human_review: needsReview,
    review_reason: out.review_reason || 'judge output unparseable -- defaulted to review',
    status: needsReview ? 'pending_review' : (lead.tier === 'Cold' ? 'flagged' : 'ok'),
  },
};

// False branch of the "needs judge?" IF -- no judge call needed, pass through as-is.
const lead = $json;
return {
  json: {
    ...lead,
    judge_ran: false,
    needs_human_review: false,
    review_reason: null,
    status: 'ok',
  },
};

parameters.text:
=Write exactly one sentence (under 25 words) summarizing this lead for a salesperson triaging a queue. Explicitly reference the intent, the clarity of the notes, and the lead source.

Name: {{ $json.name || '(none)' }}
Company: {{ $json.company || '(none)' }}
Notes: """{{ $json.raw_notes || '(none)' }}"""
Intent: {{ $json.intent }} | Clarity: {{ $json.clarity }} | Source: {{ $json.source }} | Tier: {{ $json.tier }}

parameters.jsCode:
// Guardrail on the Summarizer's output: non-empty, capped length, mentions a real signal.
const lead = $('Merge Judge Branch').item.json;
const out = $json.output || $json;
let summary = (out.summary || out.text || '').toString().trim();
const problems = [];
if (!summary) { problems.push('empty summary'); summary = `${lead.tier} lead: intent=${lead.intent}, clarity=${lead.clarity}, source=${lead.source}.`; }
if (summary.length > 300) { problems.push('summary too long, truncated'); summary = summary.slice(0, 297) + '...'; }

return { json: { ...lead, summary, guardrail_summary_ok: problems.length === 0, guardrail_summary_problems: problems } };
